// 批量导入 memory-migration 全部项目到 OpenViking
// 依次调用 import-to-ov.mjs，每项目独立进度文件，支持中断续跑
import fs from "fs";
import path from "path";
import { spawn } from "child_process";

const BASE = "C:\\Users\\Administrator\\Documents\\deepseek-harness\\default-workspace\\memory-migration";
const SRC = path.join(BASE, "out", "distilled-projects");
const TMP = "C:\\Users\\ADMINI~1\\AppData\\Local\\Temp";
const BATCH = 4;
const GAP = 5000;

// 已完成的项目（无需重跑）
const SKIP_PROJECTS = new Set(["园区物管2.0"]);

const dirs = fs.readdirSync(SRC).filter((d) => fs.statSync(path.join(SRC, d)).isDirectory());
const projects = [];
for (const d of dirs) {
  if (SKIP_PROJECTS.has(d)) continue;
  let n = 0;
  for (const f of fs.readdirSync(path.join(SRC, d)).filter((x) => x.endsWith(".json"))) {
    const j = JSON.parse(fs.readFileSync(path.join(SRC, d, f), "utf8"));
    n += (j.memories || []).length;
  }
  if (n > 0) projects.push({ name: d, count: n });
}
// 小项目优先：快速覆盖率更高，也能尽早暴露问题
projects.sort((a, b) => a.count - b.count);

const total = projects.reduce((a, b) => a + b.count, 0);
console.log(`待导入 ${projects.length} 个项目 / ${total} 条记忆`);
fs.writeFileSync(path.join(TMP, "import-all-state.json"), JSON.stringify({ startedAt: new Date().toISOString(), projects, total }, null, 1), "utf8");

function run(project) {
  return new Promise((resolve) => {
    const doneFile = path.join(TMP, `done-${project}.json`);
    const args = [path.join(BASE, "import-to-ov.mjs"), project, `--batch=${BATCH}`, `--gap=${GAP}`];
    // 有进度文件则续跑
    if (fs.existsSync(doneFile)) args.push(`--skip=${doneFile}`);
    const p = spawn(process.execPath, args, { cwd: BASE, stdio: ["ignore", "pipe", "pipe"] });
    let out = "";
    p.stdout.on("data", (d) => {
      out += d.toString();
      // 只回显关键行，避免刷屏
      for (const line of d.toString().split("\n")) {
        if (line.includes("→") || line.includes("本次") || line.includes("失败")) console.log(`  ${project} | ${line.trim()}`);
      }
    });
    p.stderr.on("data", (d) => {
      const s = d.toString();
      if (s.trim()) console.error(`  ${project} ERR: ${s.trim().slice(0, 300)}`);
    });
    p.on("close", (code) => resolve({ code, out }));
  });
}

let i = 0;
let okCount = 0;
let failProjects = [];
for (const proj of projects) {
  i++;
  console.log(`\n[${i}/${projects.length}] ${proj.name} (${proj.count} 条)`);
  const r = await run(proj.name);
  if (r.code === 0) {
    okCount++;
  } else {
    failProjects.push(proj.name);
    console.error(`  ✗ ${proj.name} 退出码 ${r.code}`);
  }
  fs.writeFileSync(
    path.join(TMP, "import-all-progress.json"),
    JSON.stringify({ current: i, total: projects.length, okCount, failProjects, currentProject: proj.name, ts: new Date().toISOString() }, null, 1),
    "utf8"
  );
}

console.log(`\n=== 全部完成 ===`);
console.log(`成功 ${okCount} / ${projects.length} 项目`);
if (failProjects.length) console.log(`失败项目: ${failProjects.join(", ")}`);

